import * as THREE from 'three/webgpu';
import { color, uv, vec3, mix, float, positionLocal, uniform } from 'three/tsl';
import { gsap } from 'gsap';

const ENTRIES = [
  { key: 'home', label: 'HOME', hub: 'hub-home', active: true },
  { key: 'features', label: 'FEATURES', hub: 'hub-features', active: false },
  { key: 'collection', label: 'COLLECTION', hub: 'hub-collection', active: false },
  { key: 'pricing', label: 'PRICING', hub: 'hub-pricing', active: false },
  { key: 'journal', label: 'JOURNAL', hub: 'hub-journal', active: false },
];

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'nav-dock';

  const railWidth = 3.6;
  const railHeight = 0.5;

  // --- Rail geometry with brushed-metal gradient PBR ---
  const railGeo = new THREE.PlaneGeometry(railWidth, railHeight, 1, 1);
  const railMat = new THREE.MeshStandardNodeMaterial();
  const topColor = color('#1b1b23');
  const bottomColor = color('#101015');
  const vUv = uv();
  railMat.colorNode = mix(bottomColor, topColor, vUv.y);
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  if (railMat.clearcoat !== undefined) railMat.clearcoat = 0.2;
  if (railMat.anisotropy !== undefined) railMat.anisotropy = 0.6;

  const rail = new THREE.Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0.15);
  group.add(rail);

  // --- Contact shadow plane ---
  const shadowGeo = new THREE.PlaneGeometry(railWidth * 1.02, railHeight * 1.1, 1, 1);
  const shadowMat = new THREE.MeshBasicNodeMaterial();
  shadowMat.colorNode = color('#000000');
  shadowMat.transparent = true;
  shadowMat.opacity = 0.35;
  const shadowPlane = new THREE.Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, -0.06, 0.0);
  group.add(shadowPlane);

  // --- Entries ---
  const spacing = 0.68;
  const startX = -((ENTRIES.length - 1) * spacing) / 2;

  const cells = [];
  const disposables = [];
  const timelines = [];

  let activeIndex = ENTRIES.findIndex((e) => e.active);
  if (activeIndex < 0) activeIndex = 0;

  // Underline bar
  const barGeo = new THREE.PlaneGeometry(0.28, 0.025, 1, 1);
  const barMat = new THREE.MeshBasicNodeMaterial();
  barMat.colorNode = color('#ff2a38');
  if ('emissiveIntensity' in barMat) barMat.emissiveIntensity = 1.8;
  const bar = new THREE.Mesh(barGeo, barMat);
  bar.position.set(startX + activeIndex * spacing, -railHeight / 2 + 0.06 - 0.025, 0.17);
  group.add(bar);

  ENTRIES.forEach((entry, i) => {
    const cellGroup = new THREE.Group();
    const x = startX + i * spacing;
    cellGroup.position.set(x, 0, 0.16);
    group.add(cellGroup);

    const isActive = i === activeIndex;
    const textColorHex = isActive ? '#e8ecf2' : '#a6adba';
    const typo = isActive ? config.typography?.['nav-active'] : config.typography?.['nav-item'];
    const fontSize = (typo?.fontSize || 13) / 100; // scene-unit approximation
    const weight = typo?.fontWeight || 400;

    const textMesh = ctx.fontAtlas.createText({
      text: entry.label,
      font: 'JetBrains Mono',
      fontWeight: weight,
      fontSize: fontSize,
      letterSpacing: 0.08,
      color: textColorHex,
      anchor: 'center',
    });
    textMesh.position.set(0, 0, 0.01);
    cellGroup.add(textMesh);
    disposables.push(textMesh);

    // Hit cell (invisible, for interaction bounds) 0.6 x 0.34
    const hitGeo = new THREE.PlaneGeometry(0.6, 0.34, 1, 1);
    const hitMat = new THREE.MeshBasicNodeMaterial();
    hitMat.transparent = true;
    hitMat.opacity = 0.0;
    hitMat.depthWrite = false;
    const hitMesh = new THREE.Mesh(hitGeo, hitMat);
    hitMesh.name = `nav-hit-${entry.key}`;
    hitMesh.userData.entry = entry;
    hitMesh.userData.index = i;
    cellGroup.add(hitMesh);

    cells.push({ cellGroup, hitMesh, textMesh, entry, index: i });

    disposables.push(hitGeo, hitMat);
  });

  disposables.push(railGeo, railMat, shadowGeo, shadowMat, barGeo, barMat);

  // --- Mount rise-in ---
  group.position.set(config.scenePosition?.[0] ?? 0, config.scenePosition?.[1] ?? 0, config.scenePosition?.[2] ?? 0);
  const baseY = group.position.y;
  group.position.y = baseY + 0.4;
  const mountTl = gsap.timeline();
  mountTl.to(group.position, {
    y: baseY,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)',
  });
  timelines.push(mountTl);

  function setActive(index) {
    if (index === activeIndex) return;
    const prevIndex = activeIndex;
    activeIndex = index;

    cells.forEach((c) => {
      const active = c.index === index;
      const targetColor = active ? '#e8ecf2' : '#a6adba';
      if (c.textMesh.material?.colorNode !== undefined) {
        // update text color via fontAtlas helper if available
        if (ctx.fontAtlas.setColor) {
          ctx.fontAtlas.setColor(c.textMesh, targetColor);
        }
      }
    });

    const targetX = startX + index * spacing;
    const tl = gsap.timeline();
    tl.to(bar.position, {
      x: targetX,
      duration: 0.26,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    }).to(bar.scale, {
      x: 1.04,
      duration: 0.13,
      ease: 'power2.out',
    }, 0).to(bar.scale, {
      x: 1.0,
      duration: 0.13,
      ease: 'power2.out',
    }, 0.13);
    timelines.push(tl);
  }

  function onPointerEnter(entryData) {
    const cell = cells[entryData.index];
    if (!cell || cell.index === activeIndex) return;
    if (ctx.fontAtlas.setColor) ctx.fontAtlas.setColor(cell.textMesh, '#e8ecf2');
  }

  function onPointerLeave(entryData) {
    const cell = cells[entryData.index];
    if (!cell || cell.index === activeIndex) return;
    if (ctx.fontAtlas.setColor) ctx.fontAtlas.setColor(cell.textMesh, '#a6adba');
  }

  function onPointerDown(entryData) {
    const cell = cells[entryData.index];
    if (!cell) return;
    const tl = gsap.timeline();
    tl.to(cell.cellGroup.scale, {
      x: 0.97, y: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0).to(cell.cellGroup.position, {
      z: 0.16 - 0.03,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0);
    timelines.push(tl);
  }

  function onPointerUp(entryData) {
    const cell = cells[entryData.index];
    if (!cell) return;
    const tl = gsap.timeline();
    tl.to(cell.cellGroup.scale, {
      x: 1.0, y: 1.0,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0).to(cell.cellGroup.position, {
      z: 0.16,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0);
    timelines.push(tl);
    setActive(entryData.index);
    if (ctx.events?.emit) {
      ctx.events.emit('navigate', { from: `hub-${ENTRIES[activeIndex].key}`, to: entryData.entry.hub });
    }
  }

  group.userData.handlers = {
    onPointerEnter: (e) => {
      const target = e?.object?.userData?.entry ? e.object.userData : null;
      if (target) onPointerEnter(target);
    },
    onPointerLeave: (e) => {
      const target = e?.object?.userData?.entry ? e.object.userData : null;
      if (target) onPointerLeave(target);
    },
    onPointerDown: (e) => {
      const target = e?.object?.userData?.entry ? e.object.userData : null;
      if (target) onPointerDown(target);
    },
    onPointerUp: (e) => {
      const target = e?.object?.userData?.entry ? e.object.userData : null;
      if (target) onPointerUp(target);
    },
  };

  // Apply cinematic primitives (none configured, but honor contract)
  const primitives = config.cinematicPrimitives || [];
  primitives.forEach((p) => {
    if (ctx.primitives && ctx.primitives[p.name]) {
      ctx.primitives[p.name](group, p.params);
    }
  });

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    mountTl.kill();
    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });
    cells.forEach((c) => {
      if (c.textMesh?.geometry?.dispose) c.textMesh.geometry.dispose();
      if (c.textMesh?.material?.dispose) c.textMesh.material.dispose();
    });
    group.traverse((obj) => {
      if (obj.geometry?.dispose) obj.geometry.dispose();
      if (obj.material?.dispose) obj.material.dispose();
    });
  };

  return group;
}
